+{"version":3,"sources":["/workspace/repo/src/__tests__/useFieldArray/move.test.tsx"],"sourcesContent":["import React from 'react';\nimport {\n  act,\n  fireEvent,\n  render,\n  renderHook,\n  screen,\n  waitFor,\n} from '@testing-library/react';\n\nimport { VALIDATION_MODE } from '../../constants';\nimport { useFieldArray } from '../../useFieldArray';\nimport { useForm } from '../../useForm';\nimport noop from '../../utils/noop';\n\nlet i = 0;\n\njest.mock('../../logic/generateId', () => () => String(i++));\n\ndescribe('move', () => {\n  beforeEach(() => {\n    i = 0;\n  });\n\n  it.each(['isDirty', 'dirtyFields'])(\n    'should move dirtyFields into pointed position when formState.%s is defined',\n    () => {\n      const { result } = renderHook(() => {\n        const { formState, control } = useForm({\n          defaultValues: { test: [{ value: '1' }] },\n        });\n        const methods = useFieldArray({\n          control,\n          name: 'test',\n        });\n        return {\n          formState,\n          ...methods,\n        };\n      });\n\n      result.current.formState.isDirty;\n      result.current.formState.dirtyFields;\n\n      act(() => {\n        result.current.append({ value: '2' });\n      });\n\n      act(() => {\n        result.current.append({ value: '3' });\n      });\n\n      act(() => {\n        result.current.move(0, 1);\n      });\n\n      expect(result.current.formState.isDirty).toBeTruthy();\n      expect(result.current.formState.dirtyFields).toEqual({\n        test: [{ value: true }, { value: true }, { value: true }],\n      });\n    },\n  );\n\n  it('should move errors', async () => {\n    let errors: any;\n    const Component = () => {\n      const { register, handleSubmit, control, ...rest } = useForm({\n        defaultValues: { test: [{ value: 'test' }] },\n      });\n      const { fields, append, move } = useFieldArray({\n        control,\n        name: 'test',\n      });\n      errors = rest.formState.errors;\n\n      return (\n        <form onSubmit={handleSubmit(noop)}>\n          {fields.map((field, i) => (\n            <input\n              key={field.id}\n              {...register(`test.${i}.value` as const, { required: true })}\n            />\n          ))}\n          <button type=\"button\" onClick={() => append({ value: '' })}>\n            append\n          </button>\n          <button type=\"button\" onClick={() => move(0, 1)}>\n            move\n          </button>\n          <button>submit</button>\n        </form>\n      );\n    };\n\n    render(<Component />);\n\n    fireEvent.click(screen.getByRole('button', { name: /append/i }));\n\n    fireEvent.click(screen.getByRole('button', { name: /submit/i }));\n\n    await waitFor(() => expect(errors.test[0]).toBeUndefined());\n    expect(errors.test[1]).toBeDefined();\n\n    fireEvent.click(screen.getByRole('button', { name: /move/i }));\n\n    expect(errors.test[0]).toBeDefined();\n    expect(errors.test[1]).toBeUndefined();\n  });\n\n  it('should move touched fields', async () => {\n    let touched: any;\n    const Component = () => {\n      const { register, formState, control } = useForm({\n        defaultValues: { test: [{ value: 'test' }] },\n      });\n      const { fields, append, move } = useFieldArray({\n        control,\n        name: 'test',\n      });\n\n      touched = formState.touchedFields;\n\n      return (\n        <form>\n          {fields.map((field, i) => (\n            <input key={field.id} {...register(`test.${i}.value` as const)} />\n          ))}\n          <button type=\"button\" onClick={() => append({ value: '' })}>\n            append\n          </button>\n          <button type=\"button\" onClick={() => move(0, 1)}>\n            move\n          </button>\n          <button>submit</button>\n        </form>\n      );\n    };\n\n    render(<Component />);\n\n    fireEvent.click(screen.getByRole('button', { name: /append/i }));\n\n    fireEvent.blur(screen.getAllByRole('textbox')[0]);\n\n    fireEvent.click(screen.getByRole('button', { name: /move/i }));\n\n    expect(touched).toEqual({\n      test: [undefined, { value: true }],\n    });\n  });\n\n  it('should trigger reRender when user is watching the all field array', () => {\n    const watched: any[] = [];\n    const Component = () => {\n      const { register, watch, control } = useForm({\n        defaultValues: {\n          test: [{ value: '1' }, { value: '2' }],\n        },\n      });\n      const { fields, move } = useFieldArray({\n        control,\n        name: 'test',\n      });\n      watched.push(watch());\n\n      return (\n        <form>\n          {fields.map((field, i) => (\n            <input key={field.id} {...register(`test.${i}.value` as const)} />\n          ))}\n          <button type=\"button\" onClick={() => move(0, 1)}>\n            move\n          </button>\n        </form>\n      );\n    };\n\n    render(<Component />);\n\n    fireEvent.click(screen.getByRole('button', { name: 'move' }));\n\n    expect(watched).toEqual([\n      { test: [{ value: '1' }, { value: '2' }] }, // first render\n      { test: [{ value: '1' }, { value: '2' }] }, // render inside useEffect in useFieldArray\n      { test: [{ value: '2' }, { value: '1' }] }, // render inside move method\n      { test: [{ value: '2' }, { value: '1' }] }, // render inside useEffect in useFieldArray\n    ]);\n  });\n\n  it('should populate all fields with default values', () => {\n    let getValues: any;\n    const Component = () => {\n      const {\n        register,\n        control,\n        getValues: tempGetValues,\n      } = useForm({\n        defaultValues: {\n          test: [{ value: '1' }, { value: '2' }],\n        },\n      });\n      const { fields } = useFieldArray({\n        control,\n        name: 'test',\n      });\n      getValues = tempGetValues;\n\n      return (\n        <form>\n          {fields.map((field, i) => (\n            <input key={field.id} {...register(`test.${i}.value` as const)} />\n          ))}\n        </form>\n      );\n    };\n\n    render(<Component />);\n\n    expect(getValues()).toEqual({ test: [{ value: '1' }, { value: '2' }] });\n  });\n\n  it('should return watched value with watch API', async () => {\n    const renderedItems: any = [];\n    const Component = () => {\n      const { watch, register, control } = useForm<{\n        test: {\n          value: string;\n        }[];\n      }>();\n      const { fields, append, move } = useFieldArray({\n        name: 'test',\n        control,\n      });\n      const watched = watch('test');\n      const isMoved = React.useRef(false);\n      if (isMoved.current) {\n        renderedItems.push(watched);\n      }\n\n      return (\n        <div>\n          {fields.map((field, i) => (\n            <div key={`${field.id}`}>\n              <input {...register(`test.${i}.value` as const)} />\n            </div>\n          ))}\n          <button onClick={() => append({ value: '' })}>append</button>\n          <button\n            onClick={() => {\n              move(0, 1);\n              isMoved.current = true;\n            }}\n          >\n            move\n          </button>\n        </div>\n      );\n    };\n\n    render(<Component />);\n\n    fireEvent.click(screen.getByRole('button', { name: /append/i }));\n    fireEvent.click(screen.getByRole('button', { name: /append/i }));\n\n    const inputs = screen.getAllByRole('textbox');\n\n    fireEvent.change(inputs[0], {\n      target: { name: 'test[0].value', value: '111' },\n    });\n    fireEvent.change(inputs[1], {\n      target: { name: 'test[1].value', value: '222' },\n    });\n\n    fireEvent.click(screen.getByRole('button', { name: /move/i }));\n\n    await waitFor(() =>\n      expect(renderedItems).toEqual([\n        [{ value: '222' }, { value: '111' }],\n        [{ value: '222' }, { value: '111' }],\n      ]),\n    );\n  });\n\n  describe('with resolver', () => {\n    it('should invoke resolver when formState.isValid true', async () => {\n      const resolver = jest.fn().mockReturnValue({});\n\n      const { result } = renderHook(() => {\n        const { formState, control } = useForm({\n          mode: VALIDATION_MODE.onChange,\n          resolver,\n          defaultValues: {\n            test: [{ value: '1' }, { value: '2' }],\n          },\n        });\n        const { move } = useFieldArray({ control, name: 'test' });\n        return { formState, move };\n      });\n\n      result.current.formState.isValid;\n\n      await act(async () => {\n        result.current.move(0, 1);\n      });\n\n      expect(resolver).toHaveBeenCalledWith(\n        {\n          test: [{ value: '2' }, { value: '1' }],\n        },\n        undefined,\n        {\n          criteriaMode: undefined,\n          fields: {},\n          names: [],\n        },\n      );\n    });\n\n    it('should not invoke resolver when formState.isValid false', () => {\n      const resolver = jest.fn().mockReturnValue({});\n\n      const { result } = renderHook(() => {\n        const { formState, control } = useForm({\n          mode: VALIDATION_MODE.onChange,\n          resolver,\n          defaultValues: {\n            test: [{ value: '1' }, { value: '2' }],\n          },\n        });\n        const { move } = useFieldArray({ control, name: 'test' });\n        return { formState, move };\n      });\n\n      act(() => {\n        result.current.move(0, 1);\n      });\n\n      expect(resolver).toHaveBeenCalled();\n    });\n  });\n\n  it('should not omit keyName when provided', async () => {\n    type FormValues = {\n      test: {\n        test: string;\n        id: string;\n      }[];\n    };\n\n    const App = () => {\n      const [data, setData] = React.useState<FormValues>();\n      const { control, register, handleSubmit } = useForm<FormValues>({\n        defaultValues: {\n          test: [\n            { id: '1234', test: 'data' },\n            { id: '4567', test: 'data1' },\n          ],\n        },\n      });\n\n      const { fields, move } = useFieldArray({\n        control,\n        name: 'test',\n      });\n\n      return (\n        <form onSubmit={handleSubmit(setData)}>\n          {fields.map((field, index) => {\n            return <input key={field.id} {...register(`test.${index}.test`)} />;\n          })}\n          <button\n            type={'button'}\n            onClick={() => {\n              move(0, 1);\n            }}\n          >\n            move\n          </button>\n          <button>submit</button>\n          <p>{JSON.stringify(data)}</p>\n        </form>\n      );\n    };\n\n    render(<App />);\n\n    fireEvent.click(screen.getByRole('button', { name: 'move' }));\n\n    fireEvent.click(screen.getByRole('button', { name: 'submit' }));\n\n    expect(\n      await screen.findByText(\n        '{\"test\":[{\"id\":\"4567\",\"test\":\"data1\"},{\"id\":\"1234\",\"test\":\"data\"}]}',\n      ),\n    ).toBeVisible();\n  });\n\n  it('should not omit keyName when provided and defaultValue is empty', async () => {\n    type FormValues = {\n      test: {\n        test: string;\n        id: string;\n      }[];\n    };\n    let k = 0;\n\n    const App = () => {\n      const [data, setData] = React.useState<FormValues>();\n      const { control, register, handleSubmit } = useForm<FormValues>();\n\n      const { fields, append, move } = useFieldArray({\n        control,\n        name: 'test',\n      });\n\n      return (\n        <form onSubmit={handleSubmit(setData)}>\n          {fields.map((field, index) => {\n            return <input key={field.id} {...register(`test.${index}.test`)} />;\n          })}\n          <button\n            type={'button'}\n            onClick={() => {\n              move(0, 1);\n            }}\n          >\n            move\n          </button>\n\n          <button\n            type={'button'}\n            onClick={() => {\n              append({\n                id: 'whatever' + k,\n                test: '1234' + k,\n              });\n              k = 1;\n            }}\n          >