+{"version":3,"sources":["/workspace/repo/src/__tests__/useFieldArray/update.test.tsx"],"sourcesContent":["import React from 'react';\nimport {\n  act,\n  fireEvent,\n  render,\n  renderHook,\n  screen,\n  waitFor,\n} from '@testing-library/react';\n\nimport { VALIDATION_MODE } from '../../constants';\nimport type { Control } from '../../types';\nimport { useController } from '../../useController';\nimport { useFieldArray } from '../../useFieldArray';\nimport { useForm } from '../../useForm';\n\nlet i = 0;\n\njest.mock('../../logic/generateId', () => () => String(i++));\n\ndescribe('update', () => {\n  beforeEach(() => {\n    i = 0;\n  });\n\n  it('should update dirtyFields fields correctly', async () => {\n    let dirtyInputs = {};\n    const Component = () => {\n      const {\n        register,\n        control,\n        formState: { dirtyFields },\n      } = useForm<{\n        test: { value: string }[];\n      }>({\n        defaultValues: {\n          test: [\n            { value: 'plz change' },\n            { value: 'dont change' },\n            { value: 'dont change' },\n          ],\n        },\n      });\n      const { fields, update } = useFieldArray({\n        control,\n        name: 'test',\n      });\n\n      dirtyInputs = dirtyFields;\n\n      return (\n        <form>\n          {fields.map((field, i) => (\n            <input key={field.id} {...register(`test.${i}.value` as const)} />\n          ))}\n          <button type=\"button\" onClick={() => update(0, { value: 'changed' })}>\n            update\n          </button>\n          {dirtyFields.test?.length && 'dirty'}\n        </form>\n      );\n    };\n\n    render(<Component />);\n\n    fireEvent.click(screen.getByRole('button'));\n\n    expect(await screen.findByText('dirty')).toBeVisible();\n\n    expect(dirtyInputs).toEqual({\n      test: [{ value: true }, { value: false }, { value: false }],\n    });\n  });\n\n  it.each(['isDirty', 'dirtyFields'])('should update state with %s', () => {\n    let isDirtyValue;\n    let dirtyValue;\n\n    const Component = () => {\n      const {\n        register,\n        control,\n        formState: { isDirty, dirtyFields },\n      } = useForm<{\n        test: { test: string }[];\n      }>({\n        defaultValues: {},\n      });\n      const { fields, update } = useFieldArray({\n        control,\n        name: 'test',\n      });\n\n      isDirtyValue = isDirty;\n      dirtyValue = dirtyFields;\n\n      return (\n        <form>\n          {fields.map((field, index) => {\n            return (\n              <input\n                key={field.id}\n                {...register(`test.${index}.test` as const)}\n              />\n            );\n          })}\n          <button type={'button'} onClick={() => update(2, { test: 'test1' })}>\n            update\n          </button>\n        </form>\n      );\n    };\n\n    render(<Component />);\n\n    fireEvent.click(screen.getByRole('button', { name: 'update' }));\n\n    expect(isDirtyValue).toBeTruthy();\n    expect(dirtyValue).toEqual({\n      test: [undefined, undefined, { test: true }],\n    });\n  });\n\n  it('should trigger reRender when user update input and is watching the all field array', () => {\n    const watched: any[] = [];\n    const Component = () => {\n      const { register, watch, control } = useForm<{\n        test: { value: string }[];\n      }>();\n      const { fields, update } = useFieldArray({\n        control,\n        name: 'test',\n      });\n      watched.push(watch());\n\n      return (\n        <form>\n          {fields.map((field, i) => (\n            <input key={field.id} {...register(`test.${i}.value` as const)} />\n          ))}\n          <button type=\"button\" onClick={() => update(0, { value: '' })}>\n            update\n          </button>\n        </form>\n      );\n    };\n\n    render(<Component />);\n\n    expect(watched).toEqual([\n      {},\n      {\n        test: [],\n      },\n    ]);\n\n    fireEvent.click(screen.getByRole('button', { name: /update/i }));\n\n    expect(watched).toEqual([\n      {},\n      {\n        test: [],\n      },\n      {\n        test: [\n          {\n            value: '',\n          },\n        ],\n      },\n      {\n        test: [\n          {\n            value: '',\n          },\n        ],\n      },\n    ]);\n  });\n\n  it('should return watched value with update and watch API', async () => {\n    const renderedItems: any = [];\n    const Component = () => {\n      const { watch, register, control } = useForm<{\n        test: { value: string }[];\n      }>();\n      const { fields, update } = useFieldArray({\n        name: 'test',\n        control,\n      });\n      const watched = watch('test');\n      renderedItems.push(watched);\n      return (\n        <div>\n          {fields.map((field, i) => (\n            <div key={field.id}>\n              <input {...register(`test.${i}.value` as const)} />\n            </div>\n          ))}\n          <button onClick={() => update(0, { value: 'test' })}>update</button>\n        </div>\n      );\n    };\n\n    render(<Component />);\n\n    fireEvent.click(screen.getByRole('button', { name: /update/i }));\n\n    await waitFor(() =>\n      expect(renderedItems).toEqual([\n        undefined,\n        [],\n        [{ value: 'test' }],\n        [{ value: 'test' }],\n      ]),\n    );\n  });\n\n  it('should update group input correctly', () => {\n    type FormValues = {\n      test: {\n        value: {\n          firstName: string;\n          lastName: string;\n        };\n      }[];\n    };\n\n    const fieldArrayValues: unknown[] = [];\n\n    const GroupInput = ({\n      control,\n      index,\n    }: {\n      control: Control<FormValues>;\n      index: number;\n    }) => {\n      const { field } = useController({\n        control,\n        name: `test.${index}.value` as const,\n      });\n\n      return (\n        <div>\n          <input\n            value={field.value.firstName}\n            onChange={(e) => {\n           