codesandbox.io/s/react-hook-form-v7-form-context-ytudi)\n *\n * @param props - all useForm methods\n *\n * @example\n * ```tsx\n * function App() {\n *   const methods = useForm();\n *   const onSubmit = data => console.log(data);\n *\n *   return (\n *     <FormProvider {...methods} >\n *       <form onSubmit={methods.handleSubmit(onSubmit)}>\n *         <NestedInput />\n *         <input type=\"submit\" />\n *       </form>\n *     </FormProvider>\n *   );\n * }\n *\n *  function NestedInput() {\n *   const { register } = useFormContext(); // retrieve all hook methods\n *   return <input {...register(\"test\")} />;\n * }\n * ```\n */\nexport const FormProvider = <\n  TFieldValues extends FieldValues,\n  TContext = any,\n  TTransformedValues = TFieldValues,\n>(\n  props: FormProviderProps<TFieldValues, TContext, TTransformedValues>,\n) => {\n  const {\n    children,\n    watch,\n    getValues,\n    getFieldState,\n    setError,\n    clearErrors,\n    setValue,\n    trigger,\n    formState,\n    resetField,\n    reset,\n    handleSubmit,\n    unregister,\n    control,\n    register,\n    setFocus,\n    subscribe,\n  } = props;\n\n  return (\n    <HookFormContext.Provider\n      value={\n        React.useMemo(\n          () => ({\n            watch,\n            getValues,\n            getFieldState,\n            setError,\n            clearErrors,\n            setValue,\n            trigger,\n            formState,\n            resetField,\n            reset,\n            handleSubmit,\n            unregister,\n            control,\n            register,\n            setFocus,\n            subscribe,\n          }),\n          [\n            clearErrors,\n            control,\n            formState,\n            getFieldState,\n            getValues,\n            handleSubmit,\n            register,\n            reset,\n            resetField,\n            setError,\n            setFocus,\n            setValue,\n            subscribe,\n            trigger,\n         