+{"version":3,"sources":["/workspace/repo/src/__tests__/useFieldArray/remove.test.tsx"],"sourcesContent":["import React from 'react';\nimport {\n  act,\n  fireEvent,\n  render,\n  renderHook,\n  screen,\n  waitFor,\n} from '@testing-library/react';\n\nimport { VALIDATION_MODE } from '../../constants';\nimport { Controller } from '../../controller';\nimport type { Control, DeepMap, FieldError } from '../../types';\nimport { useFieldArray } from '../../useFieldArray';\nimport { useForm } from '../../useForm';\nimport noop from '../../utils/noop';\n\njest.useFakeTimers();\n\nlet i = 0;\n\njest.mock('../../logic/generateId', () => () => String(i++));\n\ndescribe('remove', () => {\n  beforeEach(() => {\n    i = 0;\n  });\n\n  it('should update isDirty formState when item removed', () => {\n    let formState: any;\n    const Component = () => {\n      const {\n        register,\n        control,\n        formState: tempFormState,\n      } = useForm({\n        defaultValues: {\n          test: [{ name: 'default' }],\n        },\n      });\n      const { fields, remove, append } = useFieldArray({\n        name: 'test',\n        control,\n      });\n\n      formState = tempFormState;\n      formState.isDirty;\n\n      return (\n        <form>\n          {fields.map((field, i) => (\n            <div key={field.id}>\n              <input {...register(`test.${i}.name` as const)} />\n              <button type={'button'} onClick={() => remove(i)}>\n                remove\n              </button>\n            </div>\n          ))}\n\n          <button\n            type={'button'}\n            onClick={() =>\n              append({\n                name: '',\n              })\n            }\n          >\n            append\n          </button>\n        </form>\n      );\n    };\n\n    render(<Component />);\n\n    expect(formState.isDirty).toBeFalsy();\n\n    fireEvent.click(screen.getByRole('button', { name: /append/i }));\n\n    expect(formState.isDirty).toBeTruthy();\n\n    fireEvent.click(screen.getAllByRole('button', { name: /remove/i })[1]);\n\n    expect(formState.isDirty).toBeFalsy();\n  });\n\n  it('should update isValid formState when item removed', async () => {\n    let formState: any;\n    const Component = () => {\n      const {\n        register,\n        control,\n        formState: tempFormState,\n      } = useForm({\n        mode: 'onChange',\n        defaultValues: {\n          test: [{ name: 'default' }],\n        },\n      });\n      const { fields, remove, append } = useFieldArray({\n        name: 'test',\n        control,\n      });\n\n      formState = tempFormState;\n\n      formState.isValid;\n\n      return (\n        <form>\n          {fields.map((field, i) => (\n            <div key={field.id}>\n              <input\n                {...register(`test.${i}.name` as const, { required: true })}\n              />\n              <button type={'button'} onClick={() => remove(i)}>\n                remove\n              </button>\n            </div>\n          ))}\n\n          <button\n            type={'button'}\n            onClick={() =>\n              append({\n                name: '',\n              })\n            }\n          >\n            append\n          </button>\n\n          <p>{formState.isValid ? 'isValid' : 'notValid'}</p>\n        </form>\n      );\n    };\n\n    render(<Component />);\n\n    fireEvent.click(screen.getByRole('button', { name: /append/i }));\n\n    expect(await screen.findByText('notValid')).toBeVisible();\n\n    fireEvent.click(screen.getAllByRole('button', { name: /remove/i })[1]);\n\n    expect(await screen.findByText('isValid')).toBeVisible();\n  });\n\n  it('should remove field according index', () => {\n    const { result } = renderHook(() => {\n      const { control } = useForm({\n        defaultValues: {\n          test: [{ value: 'default' }],\n        },\n      });\n      return useFieldArray({\n        control,\n        name: 'test',\n      });\n    });\n\n    act(() => {\n      result.current.append({ value: 'test' });\n    });\n\n    act(() => {\n      result.current.remove(1);\n    });\n\n    expect(result.current.fields).toEqual([{ id: '0', value: 'default' }]);\n\n    act(() => {\n      result.current.remove(0);\n    });\n\n    expect(result.current.fields).toEqual([]);\n  });\n\n  it('should remove all field', () => {\n    const { result } = renderHook(() => {\n      const { control } = useForm({\n        defaultValues: {\n          test: [{ value: 'default' }],\n        },\n      });\n      return useFieldArray({\n        control,\n        name: 'test',\n      });\n    });\n\n    act(() => {\n      result.current.append({ value: 'test' });\n    });\n\n    act(() => {\n      result.current.remove();\n    });\n\n    expect(result.current.fields).toEqual([]);\n  });\n\n  it('should remove specific fields when index is array', () => {\n    const { result } = renderHook(() => {\n      const { control } = useForm({\n        defaultValues: {\n          test: [{ value: 'default' }],\n        },\n      });\n      return useFieldArray({\n        control,\n        name: 'test',\n      });\n    });\n\n    act(() => {\n      result.current.append({ value: 'test' });\n    });\n\n    act(() => {\n      result.current.remove([0, 1]);\n    });\n\n    expect(result.current.fields).toEqual([]);\n  });\n\n  it.each(['isDirty', 'dirtyFields'])(\n    'should be dirtyFields when value is remove with %s',\n    () => {\n      const { result } = renderHook(() => {\n        const { register, formState, control } = useForm({\n          defaultValues: {\n            test: [{ value: 'default' }],\n          },\n        });\n        const { fields, append, remove } = useFieldArray({\n          control,\n          name: 'test',\n        });\n\n        return { register, formState, fields, append, remove };\n      });\n\n      result.current.formState.isDirty;\n      result.current.formState.dirtyFields;\n\n      act(() => {\n        result.current.append({ value: 'test' });\n      });\n\n      act(() => {\n        result.current.append({ value: 'test' });\n      });\n\n      act(() => {\n        result.current.remove(0);\n      });\n\n      expect(result.current.formState.isDirty).toBeTruthy();\n      expect(result.current.formState.dirtyFields).toEqual({\n        test: [{ value: true }, { value: true }],\n      });\n\n      act(() => {\n        result.current.remove();\n      });\n\n      expect(result.current.formState.isDirty).toBeTruthy();\n      expect(result.current.formState.dirtyFields).toEqual({\n        test: [{ value: true }],\n      });\n    },\n  );\n\n  it('should remove values from formState.touchedFields', () => {\n    let touched: any;\n\n    const Component = () => {\n      const { register, formState, control } = useForm();\n      const { fields, append, remove } = useFieldArray({\n        control,\n        name: 'test',\n      });\n\n      touched = formState.touchedFields;\n\n      return (\n        <form>\n          {fields.map((field, i) => (\n            <input key={field.id} {...register(`test.${i}.value`)} />\n          ))}\n          <button type=\"button\" onClick={() => append({ value: 'append' })}>\n            append\n          </button>\n          <button type=\"button\" onClick={() => remove(0)}>\n            remove\n          </button>\n          <button type=\"button\" onClick={() => remove()}>\n            remove all\n          </button>\n        </form>\n      );\n    };\n\n    render(<Component />);\n\n    fireEvent.click(screen.getByRole('button', { name: /append/i }));\n    fireEvent.click(screen.getByRole('button', { name: /append/i }));\n    fireEvent.click(screen.getByRole('button', { name: /append/i }));\n\n    const inputs = screen.getAllByRole('textbox');\n\n    fireEvent.blur(inputs[0]);\n    fireEvent.blur(inputs[1]);\n    fireEvent.blur(inputs[2]);\n\n    expect(touched).toEqual({\n      test: [{ value: true }, { value: true }, { value: true }],\n    });\n\n    fireEvent.click(screen.getByRole('button', { name: 'remove' }));\n\n    expect(touched).toEqual({\n      test: [{ value: true }, { value: true }],\n    });\n\n    fireEvent.click(screen.getByRole('button', { name: 'remove all' }));\n\n    expect(touched).toEqual({ test: [] });\n  });\n\n  it('should remove specific field if isValid is true', async () => {\n    const Component = () => {\n      const { register, formState, control } = useForm({\n        mode: VALIDATION_MODE.onChange,\n      });\n      const { fields, append, remove } = useFieldArray({\n        control,\n        name: 'test',\n      });\n\n      formState.isValid;\n\n      return (\n        <form>\n          {fields.map((field, i) => (\n            <input\n              key={field.id}\n              {...register(`test.${i}.value` as const, { required: true })}\n            />\n          ))}\n          <button type=\"button\" onClick={() => append({ value: '' })}>\n            append\n          </button>\n          <button type=\"button\" onClick={() => remove(1)}>\n            remove\n          </button>\n          <p>{formState.isValid ? 'valid' : 'notValid'}</p>\n        </form>\n      );\n    };\n\n    render(<Component />);\n\n    fireEvent.click(screen.getByRole('button', { name: /append/i }));\n\n    expect(await screen.findByText('notValid')).toBeVisible();\n\n    fireEvent.click(screen.getByRole('button', { name: /append/i }));\n\n    fireEvent.click(screen.getByRole('button', { name: /append/i }));\n\n    fireEvent.click(screen.getByRole('button', { name: /append/i }));\n\n    const inputs = screen.getAllByRole('textbox');\n\n    fireEvent.input(inputs[0], {\n      target: { value: 'test' },\n    });\n\n    fireEvent.input(inputs[2], {\n      target: { value: 'test' },\n    });\n\n    fireEvent.input(inputs[3], {\n      target: { value: 'test' },\n    });\n\n    expect(await screen.findByText('notValid')).toBeVisible();\n\n    fireEvent.click(screen.getByRole('button', { name: 'remove' }));\n\n    expect(await screen.findByText('valid')).toBeVisible();\n  });\n\n  it('should remove all field if isValid is true', async () => {\n    let isValid = false;\n    const Component = () => {\n      const { register, formState, control } = useForm({\n        mode: VALIDATION_MODE.onChange,\n      });\n      const { fields, append, remove } = useFieldArray({\n        control,\n        name: 'test',\n      });\n      isValid = formState.isValid;\n\n      return (\n        <form>\n          {fields.map((field, i) => (\n            <input\n              key={field.id}\n              {...register(`test.${i}.value` as const, { required: true })}\n            />\n          ))}\n          <button type=\"button\" onClick={() => append({ value: '' })}>\n            append\n          </button>\n          <button type=\"button\" onClick={() => remove()}>\n            remove\n          </button>\n        </form>\n      );\n    };\n\n    render(<Component />);\n\n    fireEvent.click(screen.getByRole('button', { name: /append/i }));\n    await waitFor(() => expect(isValid).toBeFalsy());\n    expect(screen.getAllByRole('textbox')).toHaveLength(1);\n\n    fireEvent.click(screen.getByRole('button', { name: /append/i }));\n    expect(screen.getAllByRole('textbox')).toHaveLength(2);\n\n    fireEvent.click(screen.getByRole('button', { name: /append/i }));\n    await waitFor(() => expect(isValid).toBeFalsy());\n    expect(screen.getAllByRole('textbox')).toHaveLength(3);\n\n    fireEvent.click(screen.getByRole('button', { name: 'remove' }));\n    await waitFor(() => expect(isValid).toBe(true));\n  });\n\n  it('should remove error', async () => {\n    let errors: any;\n    const Component = () => {\n      const {\n        register,\n        formState: { errors: tempErrors },\n        handleSubmit,\n        control,\n      } = useForm();\n      const { fields, append, remove } = useFieldArray({\n        control,\n        name: 'test',\n      });\n      errors = tempErrors;\n\n      return (\n        